import{_ as t,c as e,o as r,a0 as a}from"./chunks/framework.DKRgXLPU.js";const n=JSON.parse('{"title":"Mal for målsetting og sporing","description":"","frontmatter":{},"headers":[],"relativePath":"no/goal-template.md","filePath":"no/goal-template.md"}');const i=t({name:"no/goal-template.md"},[["render",function(t,n,i,l,o,d){return r(),e("div",null,[...n[0]||(n[0]=[a('<h1 id="mal-for-malsetting-og-sporing" tabindex="-1">Mal for målsetting og sporing <a class="header-anchor" href="#mal-for-malsetting-og-sporing" aria-label="Permalink to &quot;Mal for målsetting og sporing&quot;">​</a></h1><h2 id="slik-bruker-du-denne-malen" tabindex="-1">Slik bruker du denne malen <a class="header-anchor" href="#slik-bruker-du-denne-malen" aria-label="Permalink to &quot;Slik bruker du denne malen&quot;">​</a></h2><p>Denne malen hjelper deg med å sette meningsfulle mål og systematisk spore fremgangen din. Kopier delene nedenfor til ditt foretrukne format (Word, Google Dokumenter, Excel, Google Regneark eller en notatbok).</p><div class="tip custom-block"><p class="custom-block-title">Målsettingsfilosofien</p><p><strong>Mål uten sporing er bare ønsker. Sporing uten refleksjon er bare data.</strong> Denne malen kombinerer begge deler: tydelig målsetting med strukturert refleksjon for å sikre kontinuerlig forbedring.</p></div><h2 id="mal-for-arlig-malsetting" tabindex="-1">Mal for årlig målsetting <a class="header-anchor" href="#mal-for-arlig-malsetting" aria-label="Permalink to &quot;Mal for årlig målsetting&quot;">​</a></h2><h3 id="kopier-denne-delen-til-dokumentet-ditt" tabindex="-1">Kopier denne delen til dokumentet ditt <a class="header-anchor" href="#kopier-denne-delen-til-dokumentet-ditt" aria-label="Permalink to &quot;Kopier denne delen til dokumentet ditt&quot;">​</a></h3><hr><p><strong>Year:</strong> ________</p><p><strong>My Pétanque Vision for This Year:</strong></p><p>(In one sentence, what do I want to achieve this year?)</p><hr><h3 id="_1-konkurransemal" tabindex="-1">1. Konkurransemål <a class="header-anchor" href="#_1-konkurransemal" aria-label="Permalink to &quot;1. Konkurransemål&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Måltype</th><th>Spesifikt mål</th><th>Hvorfor dette er viktig</th><th>Suksessmåling</th></tr></thead><tbody><tr><td><strong>Turneringsresultater</strong></td><td>Eksempel: Topp 8 i regionalt mesterskap</td><td>For å bevise at jeg kan konkurrere på regionalt nivå</td><td>Plassering blant topp 8</td></tr><tr><td><strong>Rangering</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Konsistens</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Lagprestasjoner</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="_2-tekniske-mal" tabindex="-1">2. Tekniske mål <a class="header-anchor" href="#_2-tekniske-mal" aria-label="Permalink to &quot;2. Tekniske mål&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ferdighetsområde</th><th>Nåværende nivå (1–10)</th><th>Målnivå</th><th>Spesifikt fokus</th></tr></thead><tbody><tr><td><strong>Pekepresisjon</strong></td><td></td><td></td><td>Eksempel: 70 % innenfor 10 cm ved 7 m</td></tr><tr><td><strong>Konsistens i skyting</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Terrengtilpasning</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Utvalg av bilder</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="_3-mentale-kampmal" tabindex="-1">3. Mentale kampmål <a class="header-anchor" href="#_3-mentale-kampmal" aria-label="Permalink to &quot;3. Mentale kampmål&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Område</th><th>Nåværende tilstand</th><th>Målstat</th><th>Praksismetode</th></tr></thead><tbody><tr><td><strong>Trykkhåndtering</strong></td><td></td><td></td><td>Eksempel: Bruk 3-pustetilbakestilling før hvert skudd</td></tr><tr><td><strong>Indre kritiker</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Fokus/Konsentrasjon</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Selvtillit</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="_4-fysiske-mal" tabindex="-1">4. Fysiske mål <a class="header-anchor" href="#_4-fysiske-mal" aria-label="Permalink to &quot;4. Fysiske mål&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Område</th><th>Nåværende</th><th>Mål</th><th>Handlingsplan</th></tr></thead><tbody><tr><td><strong>Treningsnivå</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Fleksibilitet</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Utholdenhet</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Skadeforebygging</strong></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="quarterly-review-template" tabindex="-1">Quarterly Review Template <a class="header-anchor" href="#quarterly-review-template" aria-label="Permalink to &quot;Quarterly Review Template&quot;">​</a></h2><h3 id="copy-this-section-every-3-months" tabindex="-1">Copy This Section Every 3 Months <a class="header-anchor" href="#copy-this-section-every-3-months" aria-label="Permalink to &quot;Copy This Section Every 3 Months&quot;">​</a></h3><hr><p><strong>Kvartal:</strong> 1. kvartal / 2. kvartal / 3. kvartal / 4. kvartal <strong>Gjennomgangsdato:</strong> ________</p><h3 id="hva-gikk-bra" tabindex="-1">Hva gikk bra? <a class="header-anchor" href="#hva-gikk-bra" aria-label="Permalink to &quot;Hva gikk bra?&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="hva-gikk-ikke-som-planlagt" tabindex="-1">Hva gikk ikke som planlagt? <a class="header-anchor" href="#hva-gikk-ikke-som-planlagt" aria-label="Permalink to &quot;Hva gikk ikke som planlagt?&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="viktige-lærdommer" tabindex="-1">Viktige lærdommer <a class="header-anchor" href="#viktige-lærdommer" aria-label="Permalink to &quot;Viktige lærdommer&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="justeringer-for-neste-kvartal" tabindex="-1">Justeringer for neste kvartal <a class="header-anchor" href="#justeringer-for-neste-kvartal" aria-label="Permalink to &quot;Justeringer for neste kvartal&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Målområde</th><th>Opprinnelig mål</th><th>Justering nødvendig</th><th>Nytt mål</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="monthly-goal-template" tabindex="-1">Monthly Goal Template <a class="header-anchor" href="#monthly-goal-template" aria-label="Permalink to &quot;Monthly Goal Template&quot;">​</a></h2><h3 id="copy-this-section-each-month" tabindex="-1">Copy This Section Each Month <a class="header-anchor" href="#copy-this-section-each-month" aria-label="Permalink to &quot;Copy This Section Each Month&quot;">​</a></h3><hr><p><strong>Måned:</strong> ________ <strong>År:</strong> ________</p><h3 id="denne-manedens-fokus" tabindex="-1">Denne månedens fokus <a class="header-anchor" href="#denne-manedens-fokus" aria-label="Permalink to &quot;Denne månedens fokus&quot;">​</a></h3><p><strong>Primærmål:</strong></p><p><strong>Hvorfor denne måneden:</strong></p><h3 id="ukentlig-oversikt" tabindex="-1">Ukentlig oversikt <a class="header-anchor" href="#ukentlig-oversikt" aria-label="Permalink to &quot;Ukentlig oversikt&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Uke</th><th>Spesifikt mål</th><th>Treningsfokus</th><th>Konkurranse/Test</th></tr></thead><tbody><tr><td><strong>Uke 1</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Uke 2</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Uke 3</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Uke 4</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="manedlige-malinger-a-spore" tabindex="-1">Månedlige målinger å spore <a class="header-anchor" href="#manedlige-malinger-a-spore" aria-label="Permalink to &quot;Månedlige målinger å spore&quot;">​</a></h3><ul><li>[ ] Fullførte treningsøkter: _____ / _____</li><li>[ ] Konkurranser påmeldt: _____ / _____</li><li>[ ] Mental treningspraksis: _____ dager</li><li>[ ] Fysisk kondisjon: _____ økter</li><li>[ ] Refleksjon/journalføring: _____ innlegg</li></ul><hr><h2 id="weekly-planning-template" tabindex="-1">Weekly Planning Template <a class="header-anchor" href="#weekly-planning-template" aria-label="Permalink to &quot;Weekly Planning Template&quot;">​</a></h2><h3 id="copy-this-section-each-week" tabindex="-1">Copy This Section Each Week <a class="header-anchor" href="#copy-this-section-each-week" aria-label="Permalink to &quot;Copy This Section Each Week&quot;">​</a></h3><hr><p><strong>Uke med:</strong> ________</p><h3 id="denne-ukens-intensjon" tabindex="-1">Denne ukens intensjon <a class="header-anchor" href="#denne-ukens-intensjon" aria-label="Permalink to &quot;Denne ukens intensjon&quot;">​</a></h3><p>(Hva er mitt ene hovedfokus denne uken?)</p><h3 id="treningsplan" tabindex="-1">Treningsplan <a class="header-anchor" href="#treningsplan" aria-label="Permalink to &quot;Treningsplan&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dag</th><th>Aktivitet</th><th>Varighet</th><th>Fokusområde</th><th>Notater</th></tr></thead><tbody><tr><td><strong>Mandag</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Tirsdag</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Onsdag</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Torsdag</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Fredag</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Lørdag</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Søndag</strong></td><td></td><td></td><td></td><td></td></tr></tbody></table><h3 id="ukentlige-mal" tabindex="-1">Ukentlige mål <a class="header-anchor" href="#ukentlige-mal" aria-label="Permalink to &quot;Ukentlige mål&quot;">​</a></h3><ul><li>[ ] Teknisk øving: _____ timer</li><li>[ ] Konkurranse/kampspill: _____ timer</li><li>[ ] Mental trening: _____ minutter</li><li>[ ] Fysisk trening: _____ økter</li><li>[ ] Videoanalyse: _____ økter</li></ul><hr><h2 id="progress-tracking-sheet" tabindex="-1">Progress Tracking Sheet <a class="header-anchor" href="#progress-tracking-sheet" aria-label="Permalink to &quot;Progress Tracking Sheet&quot;">​</a></h2><h3 id="copy-this-to-excel-google-sheets" tabindex="-1">Copy This to Excel/Google Sheets <a class="header-anchor" href="#copy-this-to-excel-google-sheets" aria-label="Permalink to &quot;Copy This to Excel/Google Sheets&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Date</th><th>Goal Area</th><th>Target</th><th>Actual</th><th>Notes</th><th>Feeling (1-10)</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Instructions for Spreadsheet:</strong></p><ol><li>Create columns: Date, Goal Area, Target, Actual, Notes, Feeling</li><li>Add new row after each training session or competition</li><li>Use conditional formatting: Green if Actual ≥ Target, Yellow if close, Red if far off</li><li>Create charts to visualize progress over time</li></ol><hr><h2 id="konkurranseytelsessporing" tabindex="-1">Konkurranseytelsessporing <a class="header-anchor" href="#konkurranseytelsessporing" aria-label="Permalink to &quot;Konkurranseytelsessporing&quot;">​</a></h2><h3 id="kopier-dette-for-a-spore-turneringsresultater" tabindex="-1">Kopier dette for å spore turneringsresultater <a class="header-anchor" href="#kopier-dette-for-a-spore-turneringsresultater" aria-label="Permalink to &quot;Kopier dette for å spore turneringsresultater&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dato</th><th>Turnering</th><th>Runde nådd</th><th>Plassering</th><th>Viktigste styrker</th><th>Forbedringsområder</th><th>Mental tilstand (1–10)</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="goal-achievement-celebration" tabindex="-1">Goal Achievement Celebration <a class="header-anchor" href="#goal-achievement-celebration" aria-label="Permalink to &quot;Goal Achievement Celebration&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Celebrate Progress!</p><p><strong>Every goal achieved deserves recognition.</strong> When you hit a target:</p><ol><li>✅ Mark it complete</li><li>🎉 Acknowledge the effort it took</li><li>📝 Write what you learned</li><li>🎯 Set the next challenge</li></ol></div><h3 id="achievement-log" tabindex="-1">Achievement Log <a class="header-anchor" href="#achievement-log" aria-label="Permalink to &quot;Achievement Log&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Date</th><th>Goal Achieved</th><th>What It Took</th><th>Key Learning</th><th>Next Challenge</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="tips-for-effektiv-malsetting" tabindex="-1">Tips for effektiv målsetting <a class="header-anchor" href="#tips-for-effektiv-malsetting" aria-label="Permalink to &quot;Tips for effektiv målsetting&quot;">​</a></h2><h3 id="_1-start-i-det-sma-bygg-momentum" tabindex="-1">1. Start i det små, bygg momentum <a class="header-anchor" href="#_1-start-i-det-sma-bygg-momentum" aria-label="Permalink to &quot;1. Start i det små, bygg momentum&quot;">​</a></h3><p>Ikke sett deg 20 mål på én gang. Start med:</p><ul><li><strong>1 konkurransemål</strong></li><li><strong>1 teknisk mål</strong></li><li><strong>1 mentalt kampmål</strong></li></ul><p>Mestre sporing av disse før du legger til flere.</p><h3 id="_2-gjennomga-regelmessig" tabindex="-1">2. Gjennomgå regelmessig <a class="header-anchor" href="#_2-gjennomga-regelmessig" aria-label="Permalink to &quot;2. Gjennomgå regelmessig&quot;">​</a></h3><ul><li><strong>Daglig:</strong> Sjekk dagens intensjon</li><li><strong>Ukentlig:</strong> Gjennomgå ukens fremgang, planlegg neste uke</li><li><strong>Månedlig:</strong> Vurder månedlige mål, juster om nødvendig</li><li><strong>Kvartalsvis:</strong> Grundig refleksjon, større justeringer</li><li><strong>Årlig:</strong> Feir året, sett en ny visjon</li></ul><h3 id="_3-vær-ærlig-ikke-hard" tabindex="-1">3. Vær ærlig, ikke hard <a class="header-anchor" href="#_3-vær-ærlig-ikke-hard" aria-label="Permalink to &quot;3. Vær ærlig, ikke hard&quot;">​</a></h3><p>Når du bommer på et mål:</p><ul><li>❌ <strong>Ikke:</strong> «Jeg er forferdelig, jeg blir aldri bedre»</li><li>✅ <strong>Gjør:</strong> «Hva var i veien? Hva kan jeg justere?»</li></ul><h3 id="_4-koble-mal-til-hvorfor-strategien-din" tabindex="-1">4. Koble mål til hvorfor-strategien din <a class="header-anchor" href="#_4-koble-mal-til-hvorfor-strategien-din" aria-label="Permalink to &quot;4. Koble mål til hvorfor-strategien din&quot;">​</a></h3><p>Hvert mål bør være knyttet til din dypere motivasjon: – Hvorfor spiller du petanque? – Hva betyr forbedring for deg? – Hvordan vil det føles å nå dette målet?</p><h3 id="_5-gjør-det-synlig" tabindex="-1">5. Gjør det synlig <a class="header-anchor" href="#_5-gjør-det-synlig" aria-label="Permalink to &quot;5. Gjør det synlig&quot;">​</a></h3><ul><li>Skriv ut dine årlige mål og heng dem opp et sted du ser dem daglig</li><li>Angi telefonpåminnelser for ukentlige evalueringer</li><li>Del mål med treningspartneren din for ansvarliggjøring</li></ul><hr><h2 id="digital-vs-paper-tracking" tabindex="-1">Digital vs. Paper Tracking <a class="header-anchor" href="#digital-vs-paper-tracking" aria-label="Permalink to &quot;Digital vs. Paper Tracking&quot;">​</a></h2><h3 id="digital-google-sheets-excel" tabindex="-1">Digital (Google Sheets/Excel) <a class="header-anchor" href="#digital-google-sheets-excel" aria-label="Permalink to &quot;Digital (Google Sheets/Excel)&quot;">​</a></h3><p><strong>Pros:</strong></p><ul><li>Easy to update anywhere</li><li>Automatic calculations and charts</li><li>Can share with coach/training partner</li><li>Search and filter data</li></ul><p><strong>Cons:</strong></p><ul><li>Requires device</li><li>Can feel impersonal</li><li>Easy to ignore notifications</li></ul><h3 id="paper-notebook-printed-templates" tabindex="-1">Paper (Notebook/Printed Templates) <a class="header-anchor" href="#paper-notebook-printed-templates" aria-label="Permalink to &quot;Paper (Notebook/Printed Templates)&quot;">​</a></h3><p><strong>Pros:</strong></p><ul><li>Tactile, personal connection</li><li>No distractions</li><li>Easy to review during training</li><li>Satisfying to check boxes</li></ul><p><strong>Cons:</strong></p><ul><li>Can&#39;t easily create charts</li><li>Risk of losing notebook</li><li>Harder to share</li></ul><p><strong>Recommendation:</strong> Use both! Digital for data tracking, paper for daily intentions and reflections.</p><hr><h2 id="relaterte-ressurser" tabindex="-1">Relaterte ressurser <a class="header-anchor" href="#relaterte-ressurser" aria-label="Permalink to &quot;Relaterte ressurser&quot;">​</a></h2><ul><li><a href="/no/workshop">Workshop</a> - Gruppesamlinger om målsetting og mentalt spill</li><li><a href="/no/opplæringsøkt">Opplæringsøkt</a> - Øv med ansvarlighetspartnere</li><li><a href="/no/utdanning/mental-styrke">Mental styrke</a> - Bygg tankesettet for måloppnåelse</li><li><a href="/no/dagbokmal">Mal for treningsdagbok</a> - Daglig treningsregistrering</li></ul><hr><h2 id="quick-start-guide" tabindex="-1">Quick Start Guide <a class="header-anchor" href="#quick-start-guide" aria-label="Permalink to &quot;Quick Start Guide&quot;">​</a></h2><p><strong>New to goal setting? Start here:</strong></p><ol><li><strong>Week 1:</strong> Set ONE monthly goal using SMART framework</li><li><strong>Week 2:</strong> Track daily progress in simple table</li><li><strong>Week 3:</strong> Do first weekly review</li><li><strong>Week 4:</strong> Adjust goal if needed, celebrate progress</li></ol><p><strong>After one month:</strong> Add quarterly and annual goals.</p><hr><div class="warning custom-block"><p class="custom-block-title">Vanlige feil ved målsetting</p><ol><li><strong>For mange mål</strong> - Fokuset er utvannet</li><li><strong>For vag</strong> – «Bli bedre» er ikke målbart</li><li><strong>Ingen sporing</strong> – Kan ikke se fremdrift</li><li><strong>Ingen gjennomgang</strong> - Går glipp av muligheter til å justere</li><li><strong>Alt resultat, ingen prosess</strong> – Fokuser på det du kan kontrollere</li></ol></div><hr><h2 id="download-templates" tabindex="-1">Download Templates <a class="header-anchor" href="#download-templates" aria-label="Permalink to &quot;Download Templates&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Copy-Paste Ready</p><p>All templates on this page are designed to be copied directly into:</p><ul><li>Microsoft Word</li><li>Google Docs</li><li>Microsoft Excel</li><li>Google Sheets</li><li>Notion</li><li>Any note-taking app</li></ul><p>Simply select the template section you want, copy (Ctrl+C / Cmd+C), and paste into your preferred tool.</p></div><p><strong>Start with these three:</strong></p><ol><li>Annual Goal Setting Template</li><li>Weekly Planning Template</li><li>Progress Tracking Sheet</li></ol><hr><p>Bruk dette rammeverket for å gjøre målene dine spesifikke og oppnåelige:</p><h3 id="smart-malmal" tabindex="-1">SMART-målmal <a class="header-anchor" href="#smart-malmal" aria-label="Permalink to &quot;SMART-målmal&quot;">​</a></h3><p><strong>S - Spesifikk:</strong> (Hva er det egentlig jeg ønsker å oppnå?)</p><p><strong>M - Målbar:</strong> (Hvordan vet jeg at jeg har oppnådd det?)</p><p><strong>A - Oppnåelig:</strong> (Er dette realistisk gitt mitt nåværende nivå og ressurser?)</p><p><strong>R - Relevant:</strong> (Hvorfor er dette viktig for min helhetsvisjon?)</p><p><strong>T - Tidsbegrenset:</strong> (Når vil jeg oppnå dette?)</p><h3 id="eksempel-pa-smart-mal" tabindex="-1">Eksempel på SMART-mål <a class="header-anchor" href="#eksempel-pa-smart-mal" aria-label="Permalink to &quot;Eksempel på SMART-mål&quot;">​</a></h3><details class="details custom-block"><summary>Eksempel 1: Teknisk mål</summary><p><strong>S - Spesifikk:</strong> Forbedre pekepresisjonen i hardt terreng <strong>M - Målbar:</strong> Land innenfor 20 cm fra hodet 7 av 10 forsøk <strong>A - Oppnåelig:</strong> For øyeblikket på 4/10, så 7/10 er utfordrende, men realistisk <strong>R - Relevant:</strong> Hardt terreng er vanlig i regionale turneringer <strong>T - Tidsbundet:</strong> Oppnå innen utgangen av 2. kvartal (30. juni)</p></details><details class="details custom-block"><summary>Eksempel 2: Konkurransemål</summary><p><strong>S - Spesifikt:</strong> Nå semifinalen i klubbmesterskapet <strong>M - Målbar:</strong> Komme blant de 4 beste i en turnering med 32 spillere <strong>A - Oppnåelig:</strong> For tiden rangert som nummer 8–12 i klubben, forbedring er realistisk <strong>R - Relevant:</strong> Bygger selvtillit og viser fremgang <strong>T - Tidsbegrenset:</strong> Mesterskapet er 15. september</p></details><details class="details custom-block"><summary>Eksempel 3: Mentalt spillmål</summary><p><strong>S - Spesifikk:</strong> Håndtere indre kritiker under konkurranse <strong>M - Målbar:</strong> Bruk Inner Coach-omformulering etter hver bom <strong>A - Oppnåelig:</strong> Har øvd på teknikk i trening <strong>R - Relevant:</strong> Negativ selvsnakk er min største barriere <strong>T - Tidsbegrenset:</strong> Konsekvent bruk i de neste 3 turneringene</p></details><hr>',126)])])}]]);export{n as __pageData,i as default};
